# Write a recursive function to find the sum of digits of a given number.
def sumdigits(n):
  if n == 0:
    return 0
  return n % 10 + sumdigits(n // 10)
print(sumdigits(n))

"""##classes & OOP"""

# Write a class in Python for a point (1D)
# Use functions like __str__ for it. Find out what they do and write down some other dunder functions and what they do.

# class Point1D:
class point1D:
  def __init__(self, x):         # called when object is created
    self.x = x

  def __str__(self):                # called to print the object
    return f'point1D(x={self.x})'

  def __repr__(self):               # official representation
    return f'point1D({self.x})'

  def __add__(self, other):         # called when object is added
    return point1D(self.x + other.x)

  def __sub__(self, other):         # called when object is subtracted
    return point1D(self.x - other.x)

  def __eq__(self, other):         # to check equality
     return self.x == other.x

# Extend it for a Line. (2D)

# class Line2D:
class line2D:
  def __init__(self, p1, p2):
    self.p1 = p1
    self.p2 = p2

  def __str__(self):
    return f'line2D(point1D({self.p1.x}), point1D({self.p2.x}))'

  def length(self):
    return abs(self.p2.x - self.p1.x)  #abs for +ve length

#using both classes
p1 = point1D(1)
p2 = point1D(2)

print(p1)
print(repr(p2))

p3 = p1 + p2
print(p3)
print(p1 == p2)

l = line2D(p1, p2)
print(l)
print(l.length())

